#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,amount;scanf("%d %d",&n,&amount);
vector<int>c(n);for(int i=0;i<n;++i)scanf("%d",&c[i]);
vector<long long>dp(amount+1,0);dp[0]=1;
for(int co:c)for(int j=co;j<=amount;++j)dp[j]+=dp[j-co];
printf("%lld\n",dp[amount]);return 0;}

